tasks.command:
cat >> src/components/ImageCarousel.css <<EOF

.carousel-caption-overlay {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    background: linear-gradient(to top, rgba(0,0,0,0.7) 0%, rgba(0,0,0,0) 100%);
    padding: 30px 20px 20px 20px;
    box-sizing: border-box;
    color: white;
    z-index: 5;
    pointer-events: none; /* Let clicks pass through if needed */
}

.carousel-caption-overlay p {
    margin: 0;
    font-family: var(--font-sans);
    font-weight: 300;
    font-size: 1.1rem;
    text-shadow: 0 1px 3px rgba(0,0,0,0.5);
    line-height: 1.4;
}

@media (max-width: 768px) {
    .carousel-caption-overlay p {
        font-size: 0.95rem;
    }
}
EOF

cat >> src/components/InteractivePlant.css <<EOF

/* SVG Logic: Leaves are transparent to clicks to allow hitting nodes behind */
#path9 {
    pointer-events: none;
}

/* Nodes/Hotspots must be clickable */
.hotspot-group {
    cursor: pointer;
    pointer-events: all; /* Restore events for the nodes */
}
EOF

echo "
.page-loading {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 60vh;
  width: 100%;
  font-family: var(--font-serif);
  font-size: 1.2rem;
  color: var(--color-primary);
  letter-spacing: 1px;
  text-transform: uppercase;
  opacity: 0.7;
  animation: pulse 1.5s infinite ease-in-out;
}

